// Generated by scripts/build-mock.mjs — do not edit.
// ---- text.js
// Shared text helpers. Plain functions only (no imports) so the build
// script can inline this file into n8n Code nodes.

function decodeEntities(s) {
  if (!s) return '';
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '–', mdash: '—', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', hellip: '…' };
  return String(s)
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => safeFromCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => safeFromCode(parseInt(d, 10)))
    .replace(/&([a-z]+);/gi, (m, n) => (named[n.toLowerCase()] !== undefined ? named[n.toLowerCase()] : m));
}

function safeFromCode(n) {
  try { return String.fromCodePoint(n); } catch (e) { return ''; }
}

function collapseWhitespace(s) {
  return String(s || '').replace(/\s+/g, ' ').trim();
}

// Words: runs of letters/digits, allowing inner apostrophes and hyphens.
function tokenizeWords(text) {
  const m = String(text || '').match(/[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu);
  return m || [];
}

function countLetters(word) {
  const m = String(word).match(/[\p{L}\p{N}]/gu);
  return m ? m.length : 0;
}

// Sentence split on . ! ? (and runs of them) followed by whitespace or end,
// plus hard line breaks. Common abbreviations are protected first.
function splitSentences(text) {
  const abbrev = /\b(e\.g|i\.e|etc|vs|mr|mrs|ms|dr|prof|inc|ltd|no|approx|fig)\./gi;
  const protectedText = String(text || '').replace(abbrev, (m) => m.replace(/\./g, '§'));
  const parts = protectedText
    .split(/(?<=[.!?…])["'”’)]*\s+|\n+/u)
    .map((s) => collapseWhitespace(s.replace(/§/g, '.')))
    .filter((s) => tokenizeWords(s).length > 0);
  return parts;
}

function escapeRegExp(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Case-insensitive whole-phrase count with flexible whitespace/hyphens.
function countPhrase(text, phrase) {
  const words = tokenizeWords(phrase);
  if (!words.length) return 0;
  const pattern = words.map(escapeRegExp).join('[\\s\\-]+');
  const re = new RegExp('(?<![\\p{L}\\p{N}])' + pattern + '(?![\\p{L}\\p{N}])', 'giu');
  const m = String(text || '').match(re);
  return m ? m.length : 0;
}

function containsPhrase(text, phrase) {
  return countPhrase(text, phrase) > 0;
}

function firstNWords(text, n) {
  return tokenizeWords(text).slice(0, n).join(' ');
}

function clamp(n, lo, hi) {
  const x = Number(n);
  if (!Number.isFinite(x)) return lo;
  return Math.min(hi, Math.max(lo, x));
}

function round1(n) {
  return Math.round(Number(n) * 10) / 10;
}

function median(nums) {
  const a = nums.filter((n) => Number.isFinite(n)).slice().sort((x, y) => x - y);
  if (!a.length) return null;
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
}

// ---- parse.js
// Turns a fetched HTML page or pasted Markdown-ish text into one article shape:
// { source, url, title, meta_description, h1, intro, sections[], body_text,
//   word_count, h2_count }
// Depends on text.js (inlined before this file in n8n).

function stripTags(html) {
  return collapseWhitespace(decodeEntities(String(html || '').replace(/<[^>]+>/g, ' ')));
}

function pickRegion(html) {
  const candidates = [];
  const tagRe = (tag) => new RegExp('<' + tag + '\\b[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'gi');
  for (const tag of ['article', 'main']) {
    let m;
    const re = tagRe(tag);
    while ((m = re.exec(html))) candidates.push(m[1]);
    if (candidates.length) break;
  }
  if (candidates.length) {
    return candidates.sort((a, b) => b.length - a.length)[0];
  }
  const body = html.match(/<body\b[^>]*>([\s\S]*)<\/body>/i);
  return body ? body[1] : html;
}

function parseHtml(html, url) {
  let doc = String(html || '');
  const titleMatch = doc.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i);
  const metaMatch =
    doc.match(/<meta\b[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>/i) ||
    doc.match(/<meta\b[^>]*content=["']([^"']*)["'][^>]*name=["']description["'][^>]*>/i);
  const h1Match = doc.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i);

  doc = doc
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|template|iframe)\b[\s\S]*?<\/\1>/gi, ' ');
  let region = pickRegion(doc)
    .replace(/<(nav|footer|aside|form)\b[\s\S]*?<\/\1>/gi, ' ');

  region = region
    .replace(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi, (m, lvl, inner) => '\n\u0001' + lvl + '\u0002' + stripTags(inner) + '\n')
    .replace(/<(br|hr)\b[^>]*>/gi, '\n')
    .replace(/<\/(p|li|div|tr|blockquote|pre|section|ul|ol|table|dd|dt|figcaption)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  region = decodeEntities(region);

  const blocks = [];
  for (const raw of region.split('\n')) {
    const line = collapseWhitespace(raw);
    if (!line) continue;
    const hm = line.match(/^\u0001(\d)\u0002(.*)$/);
    if (hm) blocks.push({ type: 'heading', level: Number(hm[1]), text: collapseWhitespace(hm[2]) });
    else blocks.push({ type: 'text', text: line.replace(/[\u0001\u0002]/g, '') });
  }

  return buildArticle(blocks, {
    source: 'url',
    url: url || '',
    title: titleMatch ? stripTags(titleMatch[1]) : '',
    meta_description: metaMatch ? collapseWhitespace(decodeEntities(metaMatch[1])) : '',
    h1: h1Match ? stripTags(h1Match[1]) : '',
  });
}

function parsePasted(heading, content, metaDescription) {
  const blocks = [];
  for (const raw of String(content || '').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const hm = line.match(/^(#{1,6})\s+(.+)$/);
    if (hm) blocks.push({ type: 'heading', level: hm[1].length, text: collapseWhitespace(hm[2].replace(/#+$/, '')) });
    else blocks.push({ type: 'text', text: collapseWhitespace(line.replace(/^[-*+]\s+|^\d+[.)]\s+/, '')) });
  }
  const h = collapseWhitespace(heading);
  return buildArticle(blocks, {
    source: 'paste',
    url: '',
    title: h,
    meta_description: collapseWhitespace(metaDescription),
    h1: h,
  });
}

function buildArticle(blocks, base) {
  let h1 = base.h1;
  const introLines = [];
  const sections = [];
  let current = null;
  for (const b of blocks) {
    if (b.type === 'heading' && b.level === 1) {
      if (!h1) h1 = b.text;
      continue;
    }
    if (b.type === 'heading' && (b.level === 2 || b.level === 3)) {
      current = { level: b.level, heading: b.text, lines: [] };
      sections.push(current);
      continue;
    }
    // h4–h6 are treated as text inside the current section.
    const text = b.text;
    if (current) current.lines.push(text);
    else introLines.push(text);
  }

  const intro = introLines.join('\n');
  const outSections = sections.map((s) => {
    const text = s.lines.join('\n');
    return { level: s.level, heading: s.heading, text, word_count: tokenizeWords(text).length };
  });
  const bodyText = [intro].concat(outSections.map((s) => s.text)).filter(Boolean).join('\n');

  return {
    source: base.source,
    url: base.url,
    title: base.title || h1 || '',
    meta_description: base.meta_description || '',
    h1: h1 || base.title || '',
    intro,
    sections: outSections,
    body_text: bodyText,
    word_count: tokenizeWords(bodyText).length,
    h2_count: outSections.filter((s) => s.level === 2).length,
  };
}

// ---- external.js
// Parsers for SerpAPI, competitor pages and Copyscape responses.
// Depends on text.js and parse.js.

function hostOf(u) {
  const m = String(u || '').match(/^https?:\/\/([^/?#]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}

// SerpAPI Google results -> list of {url, title, snippet}
function serpOrganic(serp, limit) {
  const rows = (serp && Array.isArray(serp.organic_results)) ? serp.organic_results : [];
  return rows
    .filter((r) => r && typeof r.link === 'string' && /^https?:\/\//.test(r.link))
    .slice(0, limit || 10)
    .map((r) => ({
      url: r.link,
      title: collapseWhitespace(r.title),
      snippet: collapseWhitespace(r.snippet),
    }));
}

// Pick competitor URLs, skipping the audited article's own site and
// file types we cannot parse.
function competitorUrls(serp, ownUrl, limit) {
  const own = hostOf(ownUrl);
  return serpOrganic(serp, 10)
    .filter((r) => !own || hostOf(r.url) !== own)
    .filter((r) => !/\.(pdf|docx?|pptx?|xlsx?)(\?|$)/i.test(r.url))
    .slice(0, limit || 8);
}

function competitorOutline(html, url, fallbackTitle) {
  if (typeof html !== 'string' || html.length < 200) {
    return { url, title: fallbackTitle || '', word_count: 0, headings: [] };
  }
  const a = parseHtml(html, url);
  return {
    url,
    title: a.title || fallbackTitle || '',
    word_count: a.word_count,
    headings: a.sections.map((s) => s.heading).filter((h) => h && h.length <= 120).slice(0, 40),
  };
}

// Copyscape text search (o=csearch, c>=3, f=json) -> plagiarism result.
function parseCopyscape(resp) {
  if (!resp || typeof resp !== 'object') {
    return { checked: false, percent: null, sources: [], error: 'No response from Copyscape' };
  }
  if (resp.error) {
    return { checked: false, percent: null, sources: [], error: String(resp.error).slice(0, 200) };
  }
  const count = Number(resp.count) || 0;
  const results = Array.isArray(resp.result) ? resp.result : [];
  let percent = Number(resp.allpercentmatched);
  if (!Number.isFinite(percent)) percent = count === 0 ? 0 : NaN;
  if (!Number.isFinite(percent)) {
    return { checked: false, percent: null, sources: [], error: 'Copyscape did not return allpercentmatched (needs c=3 or more)' };
  }
  return {
    checked: true,
    percent: round1(percent),
    words_checked: Number(resp.querywords) || null,
    sources: results.slice(0, 5).map((r) => ({
      url: r.url,
      title: collapseWhitespace(r.title),
      percent: Number.isFinite(Number(r.percentmatched)) ? Number(r.percentmatched) : null,
      words: Number(r.minwordsmatched) || null,
    })),
    error: '',
  };
}

// Google Sheets values -> objects keyed by the header row.
function rowsToObjects(values) {
  const rows = Array.isArray(values) ? values : [];
  if (!rows.length) return [];
  const header = rows[0].map((h) => String(h).trim());
  return rows.slice(1).map((r, i) => {
    const o = { _row: i + 2 };
    header.forEach((h, j) => { o[h] = r[j] !== undefined ? r[j] : ''; });
    return o;
  });
}

// ---- scoring.js
// Combines every check into one report out of 100 and decides whether the
// article goes to human review.
// Depends on text.js.

const RESULTS_COLUMNS = [
  'audit_id', 'created_at', 'status', 'title', 'url', 'keyword', 'total',
  'accuracy', 'readability', 'keywords', 'sections', 'plagiarism',
  'review_reasons', 'model', 'report_json',
];

const REVIEW_COLUMNS = [
  'audit_id', 'created_at', 'title', 'url', 'total', 'review_reasons',
  'reviewer_score', 'decision', 'notes', 'reviewed_at',
];

const VALIDATION_COLUMNS = [
  'audit_id', 'title', 'my_accuracy', 'my_readability', 'my_keywords',
  'my_sections', 'my_plagiarism', 'my_total',
];

const CONCLUSION_RE = /\b(conclusion|summary|final thoughts|wrapping up|key takeaways|bottom line|in short)\b/i;
const FAQ_RE = /\b(faqs?|frequently asked|common questions)\b/i;

function plagiarismPoints(percent) {
  if (!Number.isFinite(percent)) return null;
  if (percent <= 5) return 10;
  if (percent <= 10) return 6;
  if (percent <= 15) return 2;
  return 0;
}

function depthPoints(ratio) {
  if (!Number.isFinite(ratio)) return null;
  if (ratio >= 0.9) return 4;
  if (ratio >= 0.7) return 3;
  if (ratio >= 0.5) return 2;
  if (ratio >= 0.3) return 1;
  return 0;
}

function accuracyBlock(analysis, verification) {
  const scored = analysis.sections.filter((s) => s.score !== null);
  const relevancy = scored.length
    ? Math.round(scored.reduce((n, s) => n + s.score, 0) / scored.length)
    : 0;
  const n = verification.length;
  const v = verification.filter((c) => c.status === 'verified').length;
  const u = verification.filter((c) => c.status === 'unverified').length;
  const f = verification.filter((c) => c.status === 'false').length;
  const claimsPts = n ? Math.round((12 * (v + 0.5 * u)) / n) : 12;
  const points = {
    relevancy,
    claims: claimsPts,
    freshness: analysis.freshness.score,
    title_promise: analysis.title_promise.score,
  };
  return {
    points,
    score: points.relevancy + points.claims + points.freshness + points.title_promise,
    max: 30,
    sections: analysis.sections,
    claims: verification,
    claim_counts: { total: n, verified: v, unverified: u, false: f },
    freshness_note: analysis.freshness.note,
    title_note: analysis.title_promise.note,
  };
}

function sectionsBlock(article, competitors, topics, gapFailed) {
  const usable = competitors.filter((c) => c.word_count >= 200);
  const med = median(usable.map((c) => c.word_count));
  const ratio = med ? article.word_count / med : NaN;

  let coverage = null;
  // If the AI step failed, coverage is unknown: no points, never full marks.
  if (competitors.length && !gapFailed) {
    if (!topics.length) coverage = 12;
    else {
      const covered = topics.filter((t) => t.coverage === 'covered').length;
      const thin = topics.filter((t) => t.coverage === 'thin').length;
      coverage = Math.round((12 * (covered + 0.5 * thin)) / topics.length);
    }
  }

  const introWords = tokenizeWords(article.intro).length;
  const structure = {
    intro: introWords >= 40,
    conclusion: article.sections.some((s) => CONCLUSION_RE.test(s.heading)),
    faq: article.sections.some((s) => FAQ_RE.test(s.heading)),
    enough_h2: article.h2_count >= 3,
  };
  const structurePts = [structure.intro, structure.conclusion, structure.faq, structure.enough_h2].filter(Boolean).length;
  const depth = depthPoints(ratio);

  const points = { coverage, structure: structurePts, depth };
  return {
    points,
    score: (coverage || 0) + structurePts + (depth || 0),
    max: 20,
    topics,
    structure,
    competitor_count: competitors.length,
    word_count: article.word_count,
    competitor_median_words: med ? Math.round(med) : null,
    competitors: competitors.slice(0, 10).map((c) => ({ url: c.url, title: c.title, word_count: c.word_count })),
  };
}

function plagiarismBlock(p) {
  const percent = p && p.checked && Number.isFinite(Number(p.percent)) ? Number(p.percent) : null;
  const pts = percent === null ? null : plagiarismPoints(percent);
  return {
    checked: percent !== null,
    percent,
    sources: ((p && p.sources) || []).slice(0, 5),
    error: (p && p.error) || '',
    points: { match: pts },
    score: pts || 0,
    max: 10,
  };
}

function buildReport(ctx) {
  const passMark = Number(ctx.config && ctx.config.pass_mark) || 70;
  const accuracy = accuracyBlock(ctx.analysis, ctx.verification || []);
  const readability = ctx.readability;
  const keywords = ctx.keywords;
  const sections = sectionsBlock(ctx.article, ctx.competitors || [], ctx.gap || [], ctx.gap_failed === true);
  const plagiarism = plagiarismBlock(ctx.plagiarism);

  const total = accuracy.score + readability.score + keywords.score + sections.score + plagiarism.score;

  const flags = [];
  if (accuracy.claim_counts.false > 0) {
    flags.push({ code: 'false_claim', hard: true, message: accuracy.claim_counts.false + ' claim(s) contradicted by search results' });
  }
  if (plagiarism.checked && plagiarism.percent > 15) {
    flags.push({ code: 'plagiarism_over_15', hard: true, message: 'Plagiarism match ' + plagiarism.percent + '% (over 15%)' });
  }
  if (!plagiarism.checked) {
    flags.push({ code: 'plagiarism_not_checked', hard: true, message: 'Plagiarism check did not run' + (plagiarism.error ? ': ' + plagiarism.error : '') });
  }
  if (!sections.competitor_count) {
    flags.push({ code: 'serp_unavailable', hard: true, message: 'No competitor pages fetched, so missing sections could not be checked' });
  }
  if (!ctx.article.sections.length) {
    flags.push({ code: 'no_sections', hard: false, message: 'No H2/H3 headings found' });
  }
  if (ctx.prompt_truncated) {
    flags.push({ code: 'prompt_truncated', hard: false, message: 'Long article: each section was shortened before it was sent to the AI (MAX_PROMPT_CHARS)' });
  }
  if (accuracy.claim_counts.unverified > 0) {
    flags.push({ code: 'unverified_claims', hard: false, message: accuracy.claim_counts.unverified + ' claim(s) could not be verified' });
  }
  (ctx.errors || []).forEach((e) => flags.push({ code: 'step_error', hard: true, message: String(e).slice(0, 200) }));

  const reasons = [];
  if (ctx.analysis_failed) reasons.push('AI analysis did not run, so accuracy and intent scores are incomplete');
  if (total < passMark) reasons.push('Total ' + total + ' is below ' + passMark);
  flags.filter((f) => f.hard).forEach((f) => reasons.push(f.message));

  let status = reasons.length ? 'needs_review' : 'passed';
  if (ctx.analysis_failed) status = 'error';

  return {
    audit_id: ctx.audit_id,
    created_at: ctx.created_at,
    status,
    pass_mark: passMark,
    total,
    review_reasons: reasons,
    flags,
    model: (ctx.config && ctx.config.model) || '',
    article: {
      title: ctx.article.title,
      h1: ctx.article.h1,
      url: ctx.article.url,
      source: ctx.article.source,
      word_count: ctx.article.word_count,
      meta_description: ctx.article.meta_description,
    },
    input: {
      keyword: ctx.input.keyword,
      secondary: ctx.input.secondary,
      target_grade: ctx.input.target_grade,
      market_label: ctx.input.market_label,
    },
    parameters: { accuracy, readability, keywords, sections, plagiarism },
    ai_detection: ctx.ai_detection || { checked: false },
  };
}

// Sheets cells hold at most 50,000 characters; keep a margin.
function compactReportJson(report) {
  let json = JSON.stringify(report);
  if (json.length <= 45000 || !report.parameters) return json.slice(0, 45000);
  const r = JSON.parse(json);
  r.parameters.sections.competitors = [];
  r.parameters.accuracy.sections = r.parameters.accuracy.sections.slice(0, 15);
  json = JSON.stringify(r);
  if (json.length <= 45000) return json;
  r.parameters.accuracy.claims.forEach((c) => { c.evidence = ''; });
  r.parameters.readability.hardest_sentence = null;
  return JSON.stringify(r).slice(0, 45000);
}

// For audits that stop before scoring (article could not be fetched or read).
function buildErrorReport(ctx) {
  return {
    audit_id: ctx.audit_id,
    created_at: ctx.created_at,
    status: 'error',
    error: String(ctx.error || 'The audit could not finish.').slice(0, 500),
    pass_mark: Number(ctx.config && ctx.config.pass_mark) || 70,
    total: null,
    review_reasons: [String(ctx.error || 'The audit could not finish.').slice(0, 300)],
    flags: [],
    model: (ctx.config && ctx.config.model) || '',
    article: { title: ctx.input.heading || ctx.input.url || '', h1: '', url: ctx.input.url || '', source: ctx.input.url ? 'url' : 'paste', word_count: 0, meta_description: '' },
    input: { keyword: ctx.input.keyword, secondary: ctx.input.secondary, target_grade: ctx.input.target_grade, market_label: ctx.input.market_label },
    parameters: null,
  };
}

function resultsRow(report) {
  if (!report.parameters) {
    return [
      report.audit_id, report.created_at, report.status, report.article.title, report.article.url,
      report.input.keyword, '', '', '', '', '', '', report.review_reasons.join(' | '), report.model,
      compactReportJson(report),
    ];
  }
  const p = report.parameters;
  return [
    report.audit_id, report.created_at, report.status, report.article.title, report.article.url,
    report.input.keyword, report.total, p.accuracy.score, p.readability.score, p.keywords.score,
    p.sections.score, p.plagiarism.score, report.review_reasons.join(' | '), report.model,
    compactReportJson(report),
  ];
}

function reviewRow(report) {
  return [
    report.audit_id, report.created_at, report.article.title, report.article.url, report.total,
    report.review_reasons.join(' | '), '', 'pending', '', '',
  ];
}

// ---- api.js
// Handles the web app's data requests inside the n8n "API" workflow.
// Input: the request body, plus the three sheet tabs already read in one
// batchGet. Output: the JSON response and, when needed, the cells to write.
// Depends on text.js, external.js (rowsToObjects) and scoring.js (column lists).

function colLetter(n) {
  let s = '';
  let x = n;
  while (x > 0) {
    const m = (x - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    x = Math.floor((x - 1) / 26);
  }
  return s;
}

function num(v) {
  if (v === '' || v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function summary(r) {
  return {
    audit_id: r.audit_id,
    created_at: r.created_at,
    status: r.status,
    title: r.title,
    url: r.url,
    keyword: r.keyword,
    total: num(r.total),
    accuracy: num(r.accuracy),
    readability: num(r.readability),
    keywords: num(r.keywords),
    sections: num(r.sections),
    plagiarism: num(r.plagiarism),
    review_reasons: r.review_reasons ? String(r.review_reasons).split(' | ') : [],
  };
}

function byNewest(a, b) {
  return String(b.created_at).localeCompare(String(a.created_at));
}

function writeRow(tab, columns, existingValues, auditId, rowValues, startCol) {
  // Returns batchUpdate "data" entries that set one row (inserting the
  // header first if the tab is empty).
  const data = [];
  const objs = rowsToObjects(existingValues);
  let rowNum;
  const found = objs.find((o) => o.audit_id === auditId);
  if (found) rowNum = found._row;
  else {
    if (!existingValues || !existingValues.length) {
      data.push({ range: tab + '!A1:' + colLetter(columns.length) + '1', values: [columns] });
      rowNum = 2;
    } else {
      rowNum = existingValues.length + 1;
    }
  }
  const from = startCol || 1;
  const to = from + rowValues.length - 1;
  data.push({ range: tab + '!' + colLetter(from) + rowNum + ':' + colLetter(to) + rowNum, values: [rowValues] });
  return data;
}

function handleApi(body, sheets, config) {
  const b = body && typeof body === 'object' ? body : {};
  const action = String(b.action || '');
  const results = rowsToObjects(sheets.Results);
  const reviews = rowsToObjects(sheets.Review);
  const validation = rowsToObjects(sheets.Validation);
  const passMark = Number(config && config.pass_mark) || 70;
  const ok = (response) => ({ status_code: 200, response: response, write: null });
  const bad = (msg, code) => ({ status_code: code || 400, response: { error: msg }, write: null });

  if (action === 'list') {
    const pending = reviews.filter((r) => (r.decision || 'pending') === 'pending').length;
    return ok({ audits: results.map(summary).sort(byNewest).slice(0, 100), pending_reviews: pending, pass_mark: passMark });
  }

  if (action === 'get') {
    const id = String(b.audit_id || '');
    const row = results.find((r) => r.audit_id === id);
    if (!row) return ok({ audit: null, state: 'running_or_unknown' });
    let report = null;
    try { report = JSON.parse(row.report_json); } catch (e) { report = null; }
    const rev = reviews.find((r) => r.audit_id === id) || null;
    const val = validation.find((r) => r.audit_id === id) || null;
    return ok({ audit: summary(row), report, review: rev, validation: val, pass_mark: passMark });
  }

  if (action === 'review_list') {
    const byId = new Map(results.map((r) => [r.audit_id, summary(r)]));
    const items = reviews.map((r) => ({
      audit_id: r.audit_id,
      created_at: r.created_at,
      title: r.title,
      url: r.url,
      total: num(r.total),
      review_reasons: r.review_reasons ? String(r.review_reasons).split(' | ') : [],
      reviewer_score: num(r.reviewer_score),
      decision: r.decision || 'pending',
      notes: r.notes || '',
      reviewed_at: r.reviewed_at || '',
      scores: byId.get(r.audit_id) || null,
    }));
    items.sort((x, y) => (x.decision === 'pending' ? 0 : 1) - (y.decision === 'pending' ? 0 : 1) || byNewest(x, y));
    return ok({ items });
  }

  if (action === 'review_save') {
    const id = String(b.audit_id || '');
    if (!reviews.find((r) => r.audit_id === id)) return bad('That audit is not in the review queue', 404);
    const decision = ['pending', 'approved', 'sent_back'].indexOf(b.decision) >= 0 ? b.decision : null;
    if (!decision) return bad('Decision must be approved, sent_back or pending');
    const score = num(b.reviewer_score);
    if (score !== null && (score < 0 || score > 100)) return bad('Your score must be between 0 and 100');
    const notes = String(b.notes || '').slice(0, 1000);
    const values = [score === null ? '' : score, decision, notes, new Date().toISOString()];
    // reviewer_score is column 7 (G) in REVIEW_COLUMNS
    const data = writeRow('Review', REVIEW_COLUMNS, sheets.Review, id, values, REVIEW_COLUMNS.indexOf('reviewer_score') + 1);
    return { status_code: 200, response: { saved: true }, write: { data } };
  }

  if (action === 'validation') {
    const byId = new Map(results.map((r) => [r.audit_id, summary(r)]));
    const pairs = validation.map((v) => {
      const found = byId.get(v.audit_id) || null;
      // Audits that errored have incomplete scores, so they don't count.
      const ai = found && found.status !== 'error' ? found : null;
      return {
        audit_id: v.audit_id,
        title: v.title || (ai && ai.title) || '',
        found: Boolean(ai),
        ai: ai ? { total: ai.total, accuracy: ai.accuracy, readability: ai.readability, keywords: ai.keywords, sections: ai.sections, plagiarism: ai.plagiarism } : {},
        me: {
          total: num(v.my_total), accuracy: num(v.my_accuracy), readability: num(v.my_readability),
          keywords: num(v.my_keywords), sections: num(v.my_sections), plagiarism: num(v.my_plagiarism),
        },
      };
    });
    return ok({ pairs, pass_mark: passMark, target_count: 30 });
  }

  if (action === 'validation_save') {
    const id = String(b.audit_id || '');
    const row = results.find((r) => r.audit_id === id);
    if (!row) return bad('Unknown audit', 404);
    const limits = { my_accuracy: 30, my_readability: 20, my_keywords: 20, my_sections: 20, my_plagiarism: 10 };
    const vals = {};
    for (const k of Object.keys(limits)) {
      const n = num(b[k]);
      if (n === null || n < 0 || n > limits[k]) return bad(k.replace('my_', '') + ' must be between 0 and ' + limits[k]);
      vals[k] = n;
    }
    const total = vals.my_accuracy + vals.my_readability + vals.my_keywords + vals.my_sections + vals.my_plagiarism;
    const values = [id, row.title, vals.my_accuracy, vals.my_readability, vals.my_keywords, vals.my_sections, vals.my_plagiarism, total];
    const data = writeRow('Validation', VALIDATION_COLUMNS, sheets.Validation, id, values, 1);
    return { status_code: 200, response: { saved: true, my_total: total }, write: { data } };
  }

  return bad('Unknown action');
}

export { handleApi, RESULTS_COLUMNS, REVIEW_COLUMNS };
